SELECT COUNT(*)
FROM categories
WHERE name = #{name}
  AND deleted_at IS NULL

  AND id <> #{excludeId}

SELECT COUNT(*)
FROM categories
WHERE initial = #{initial}
  AND deleted_at IS NULL

  AND id <> #{excludeId}

mapper.update:
UPDATE categories
SET name = #{name},
    initial = #{initial},
    version = version + 1,
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
WHERE id = #{id}
  AND version = #{version}
  AND deleted_at IS NULL
